func main() {
	nums := make([]int, 1000)
	for i := range nums {
		nums[i] = i + 1
	}

	const parts = 4
	size := len(nums) / parts
	partial := make([]int, parts)

	var wg sync.WaitGroup
	for p := range parts {
		wg.Go(func() {
			for _, v := range nums[p*size : (p+1)*size] {
