import (
	"fmt"
	"sync"
)

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	for d := 2; d*d <= n; d++ {
		if n%d == 0 {
			return false
		}
	}
	return true
}

func countPrimes(lo, hi int) int {
	count := 0
	for n := lo; n < hi; n++ {
		if isPrime(n) {
			count++
		}
	}
	return count
}

func main() {
	ranges := [][2]int{{0, 2500}, {2500, 5000}, {5000, 7500}, {7500, 10000}}
	counts := make([]int, len(ranges))

	var wg sync.WaitGroup
	for i, r := range ranges {
		wg.Go(func() {
			counts[i] = countPrimes(r[0], r[1])
		})
	}
	wg.Wait()

	total := 0
	for i, c := range counts {
		fmt.Printf("%d..%d: %d ta\n", ranges[i][0], ranges[i][1], c)
		total += c
	}
	fmt.Println("jami:", total)
}

