import "fmt"

type Logger struct {
	lines chan string
	done  chan struct{}
	saved []string
}

func NewLogger() *Logger {
	l := &Logger{lines: make(chan string), done: make(chan struct{})}
	go func() {
		defer close(l.done)
		for line := range l.lines {
			l.saved = append(l.saved, "[log] "+line)
		}
	}()
	return l
}

func (l *Logger) Log(s string) { l.lines <- s }

func (l *Logger) Close() {
	close(l.lines)
	<-l.done // goroutine tugashini kutamiz
}

func main() {
	l := NewLogger()
	l.Log("server ishga tushdi")
	l.Log("so'rov keldi")
	l.Close()

	for _, s := range l.saved {
		fmt.Println(s)
	}
}

