import (
	"fmt"
	"sync"
)

func merge(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	return append(out, b[j:]...)
}

func mergeSort(s []int, depth int) []int {
	if len(s) <= 1 {
		return s
	}
	mid := len(s) / 2
	var left, right []int
	if depth > 0 {
		var wg sync.WaitGroup
		wg.Go(func() { left = mergeSort(s[:mid], depth-1) })
		wg.Go(func() { right = mergeSort(s[mid:], depth-1) })
		wg.Wait()
	} else {
		left, right = mergeSort(s[:mid], 0), mergeSort(s[mid:], 0)
	}
	return merge(left, right)
}

func main() {
	data := []int{9, 3, 7, 1, 8, 2, 6, 4, 5, 0}
	fmt.Println(mergeSort(data, 2))
}

