func settle(limit int) int {
	for runtime.NumGoroutine() > limit {
		time.Sleep(time.Millisecond)
	}
	return runtime.NumGoroutine()
}

func main() {
	first(3, 3) // bufer = 3: hamma yuboruvchi chiqib ketadi
	fmt.Println("buferli:", settle(1))

