)

func parseAll(items []string) (<-chan int, <-chan error) {
	values := make(chan int, len(items))
	errs := make(chan error, len(items))
	for _, s := range items {
		n, err := strconv.Atoi(s)
		if err != nil {
			errs <- err
			continue
		}
		values <- n
	}
	close(values)
	close(errs)
	return values, errs
}

