import (
	"fmt"
	"sync"
)

func parallelSum(nums []int, parts int) int {
	size := (len(nums) + parts - 1) / parts
	partial := make([]int, parts)
	var wg sync.WaitGroup

	for p := range parts {
		lo := p * size
		hi := min(lo+size, len(nums))
		if lo >= hi {
			continue
		}
		wg.Go(func() {
			for _, v := range nums[lo:hi] {
				partial[p] += v
			}
		})
	}

	wg.Wait()
	total := 0
	for _, s := range partial {
		total += s
	}
	return total
}

func main() {
	nums := make([]int, 1000)
	for i := range nums {
		nums[i] = i + 1
	}
	fmt.Println("yig'indi:", parallelSum(nums, 4))
}

