type Group struct {
	wg   sync.WaitGroup
	once sync.Once
	err  error
}

func (g *Group) Go(f func() error) {
	g.wg.Go(func() {
		if err := f(); err != nil {
			g.once.Do(func() { g.err = err }) // faqat birinchi xato saqlanadi
		}
	})
}

func (g *Group) Wait() error {
	g.wg.Wait()
	return g.err
}

func main() {
	var g Group
	for _, host := range []string{"api", "db", "cache"} {
		g.Go(func() error {
			if host == "db" {
				return errors.New("db: ulanib bo'lmadi")
			}
			return nil
		})
	}

	if err := g.Wait(); err != nil {
		fmt.Println("xato:", err)
	}
}

