	"sync"
)

func sum(nums []int, depth int) int {
	if depth == 0 || len(nums) < 2 {
		total := 0
		for _, v := range nums {
			total += v
		}
		return total
	}

	mid := len(nums) / 2
	var left, right int
	var wg sync.WaitGroup
	wg.Go(func() { left = sum(nums[:mid], depth-1) })
	wg.Go(func() { right = sum(nums[mid:], depth-1) })
	wg.Wait()
	return left + right
}

func main() {
	nums := make([]int, 100)
	for i := range nums {
		nums[i] = i + 1
	}
	fmt.Println("yig'indi:", sum(nums, 3)) // chuqurlik 3: eng ko'pi bilan 8 ta bo'lak
}

