}

func (n *Node) Sum() int {
	partial := make([]int, len(n.Children))
	var wg sync.WaitGroup
	for i, c := range n.Children {
		wg.Go(func() { partial[i] = c.Sum() })
	}
	wg.Wait()

	total := n.Value
	for _, p := range partial {
		total += p
	}
	return total
}

