func multiply(a, b [][]int) [][]int {
	rows, inner, cols := len(a), len(b), len(b[0])
	c := make([][]int, rows)

	var wg sync.WaitGroup
	for i := range rows {
		c[i] = make([]int, cols)
		wg.Go(func() {
			for j := range cols {
				for k := range inner {
					c[i][j] += a[i][k] * b[k][j]
				}
			}
		})
	}
	wg.Wait()
	return c
}

