type Service struct {
	jobs chan string
	wg   sync.WaitGroup
	mu   sync.Mutex
	log  []string
}

func NewService(workers int) *Service {
	s := &Service{jobs: make(chan string)}
	for range workers {
		s.wg.Go(func() {
			for job := range s.jobs {
				s.mu.Lock()
				s.log = append(s.log, "bajarildi: "+job)
				s.mu.Unlock()
			}
		})
	}
	return s
}

func (s *Service) Submit(job string) { s.jobs <- job }

func (s *Service) Stop() []string {
	close(s.jobs) // yangi ish kelmaydi
	s.wg.Wait()   // ishlayotganlar tugashini kutamiz
	sort.Strings(s.log)
	return s.log
}

func main() {
	svc := NewService(3)
	for _, j := range []string{"email", "sms", "push", "report"} {
		svc.Submit(j)
	}
	for _, line := range svc.Stop() {
