	"time"
)

func waitTimeout(wg *sync.WaitGroup, d time.Duration) bool {
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
		return true
	case <-time.After(d):
		return false
	}
}

func main() {
	var wg sync.WaitGroup
	release := make(chan struct{})

	wg.Go(func() { <-release }) // release kelmaguncha tugamaydi

	fmt.Println("50 ms ichida tugadimi?", waitTimeout(&wg, 50*time.Millisecond))
	close(release)
	fmt.Println("ruxsatdan keyin tugadimi?", waitTimeout(&wg, 5*time.Second))
}

