func safely(f func()) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r)
		}
	}()
	f()
	return nil
}

func main() {
	divisors := []int{10, 0, 5}
	quotients := make([]int, len(divisors))
	errs := make([]error, len(divisors))

	var wg sync.WaitGroup
	for i, d := range divisors {
		wg.Go(func() {
			errs[i] = safely(func() { quotients[i] = 100 / d })
		})
	}
	wg.Wait()

	for i, d := range divisors {
		if errs[i] != nil {
			fmt.Printf("100 / %d -> %v\n", d, errs[i])
			continue
		}
		fmt.Printf("100 / %d = %d\n", d, quotients[i])
	}
}

