type Refresher struct {
	mu   sync.Mutex
	runs int
}

// Refresh: boshqa yangilanish ketayotgan bo'lsa kutmaydi
func (r *Refresher) Refresh() bool {
	if !r.mu.TryLock() {
		return false
	}
	defer r.mu.Unlock()
	r.runs++
	return true
}

func main() {
	r := &Refresher{}
	started := make(chan struct{})
	release := make(chan struct{})

	var wg sync.WaitGroup
	wg.Go(func() { // uzoq yangilanish: qulfni ushlab turadi
		r.mu.Lock()
		close(started)
		<-release
		r.runs++
		r.mu.Unlock()
	})

	<-started
	fmt.Println("band paytida Refresh:", r.Refresh())
	close(release)
	wg.Wait()
	fmt.Println("bo'sh paytida Refresh:", r.Refresh())
	fmt.Println("jami yangilanishlar:", r.runs)
}

