type Stack struct {
	sync.Mutex // embed: s.Lock(), s.Unlock() to'g'ridan-to'g'ri
	items      []int
}

func (s *Stack) Push(v int) {
	s.Lock()
	defer s.Unlock()
	s.items = append(s.items, v)
}

func (s *Stack) Pop() (int, bool) {
	s.Lock()
	defer s.Unlock()
	if len(s.items) == 0 {
		return 0, false
	}
	last := len(s.items) - 1
	v := s.items[last]
	s.items = s.items[:last]
	return v, true
}

func main() {
	var s Stack
	var wg sync.WaitGroup
	for i := 1; i <= 50; i++ {
		wg.Go(func() { s.Push(i) })
	}
	wg.Wait()

	sum, count := 0, 0
	for {
		v, ok := s.Pop()
		if !ok {
			break
		}
		sum += v
		count++
	}
	fmt.Println("chiqarildi:", count, "yig'indi:", sum)
}

