import (
	"fmt"
	"hash/fnv"
	"slices"
	"sync"
)

const shardCount = 4

type shard struct {
	mu sync.Mutex
	m  map[string]int
}

type ShardedCounter struct {
	shards [shardCount]shard
}

func NewShardedCounter() *ShardedCounter {
	sc := &ShardedCounter{}
	for i := range sc.shards {
		sc.shards[i].m = make(map[string]int)
	}
	return sc
}

func (sc *ShardedCounter) shardFor(key string) *shard {
	h := fnv.New32a()
	h.Write([]byte(key))
	return &sc.shards[h.Sum32()%shardCount]
}

func (sc *ShardedCounter) Inc(key string) {
	s := sc.shardFor(key)
	s.mu.Lock()
	s.m[key]++
	s.mu.Unlock()
}

func (sc *ShardedCounter) Get(key string) int {
	s := sc.shardFor(key)
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.m[key]
}

func main() {
	sc := NewShardedCounter()
	keys := []string{"olma", "nok", "uzum", "anor", "behi"}

	var wg sync.WaitGroup
	for range 200 {
		for _, k := range keys {
			wg.Go(func() { sc.Inc(k) })
		}
	}
	wg.Wait()

	slices.Sort(keys)
	for _, k := range keys {
		fmt.Printf("%s: %d\n", k, sc.Get(k))
	}
}

