type Pair struct {
	mu   sync.Mutex
	a, b int // invariant: a + b == 100
}

func (p *Pair) Move(n int) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.a -= n // bu yerda a+b vaqtincha 100 emas...
	p.b += n // ...lekin qulf tufayli buni hech kim ko'rmaydi
}

func (p *Pair) Snapshot() (int, int) {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.a, p.b
}

func main() {
	p := &Pair{a: 60, b: 40}
	broken := make([]bool, 50)

	var wg sync.WaitGroup
	for i := range 50 {
		wg.Go(func() {
			if i%2 == 0 {
				p.Move(1)
			} else {
				p.Move(-1)
			}
		})
		wg.Go(func() {
			a, b := p.Snapshot()
			broken[i] = a+b != 100
		})
	}
	wg.Wait()

	violations := 0
	for _, bad := range broken {
		if bad {
			violations++
		}
	}
	a, b := p.Snapshot()
	fmt.Println("buzilgan holatlar:", violations)
	fmt.Println("yakuniy:", a, b, "yig'indi:", a+b)
}

