	items []int
}

func NewQueue() *Queue {
	q := &Queue{}
	q.cond = sync.NewCond(&q.mu)
	return q
}

func (q *Queue) Put(v int) {
	q.mu.Lock()
	q.items = append(q.items, v)
	q.mu.Unlock()
	q.cond.Signal() // kutayotgan consumer'ni uyg'otamiz
}

func (q *Queue) Get() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	for len(q.items) == 0 { // shart for ichida tekshiriladi, if emas
		q.cond.Wait() // qulfni vaqtincha qaytarib uxlaydi
	}
	v := q.items[0]
	q.items = q.items[1:]
	return v
}

func main() {
