	got := make([]int, 0, 5)

	var wg sync.WaitGroup
	wg.Go(func() {
		for range 5 {
			got = append(got, q.Get())
		}
	})

	for v := 1; v <= 5; v++ {
		q.Put(v * 10)
	}
	wg.Wait()
	fmt.Println("consumer oldi:", got)
}

