type Queue struct {
	mu    sync.Mutex
	items []int
}

func (q *Queue) Pop() (int, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	if len(q.items) == 0 {
		return 0, false
	}
	v := q.items[0]
	q.items = q.items[1:]
	return v, true
}

func main() {
	q := &Queue{}
	for i := 1; i <= 20; i++ {
		q.items = append(q.items, i)
	}

	const workers = 4
	taken := make([][]int, workers)

	var wg sync.WaitGroup
	for w := range workers {
		wg.Go(func() {
			for {
				v, ok := q.Pop()
				if !ok {
					return
				}
				taken[w] = append(taken[w], v)
			}
		})
	}
	wg.Wait()

	count, sum := 0, 0
	seen := map[int]bool{}
	duplicates := 0
	for _, part := range taken {
		for _, v := range part {
			count++
			sum += v
			if seen[v] {
				duplicates++
			}
			seen[v] = true
		}
	}
	fmt.Println("qayta ishlangan:", count)
	fmt.Println("yig'indi:", sum)
	fmt.Println("takrorlar:", duplicates)
}

