import (
	"errors"
	"fmt"
	"sync"
)

type Bank struct {
	mu       sync.Mutex
	balances map[string]int
}

// Deposit: ochiq metod — qulfni o'zi oladi
func (b *Bank) Deposit(name string, amount int) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.deposit(name, amount)
}

// Transfer: bir qulf ostida ikkita ichki amalni chaqiradi
func (b *Bank) Transfer(from, to string, amount int) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if err := b.withdraw(from, amount); err != nil {
		return err
	}
	b.deposit(to, amount) // Deposit() chaqirilsa, ikkinchi Lock = deadlock bo'lardi
	return nil
}

// deposit va withdraw: kichik harf — chaqiruvchi qulfni ushlab turgan deb faraz qilinadi
func (b *Bank) deposit(name string, amount int) { b.balances[name] += amount }

func (b *Bank) withdraw(name string, amount int) error {
	if b.balances[name] < amount {
		return errors.New("mablag' yetarli emas")
	}
	b.balances[name] -= amount
	return nil
}

func main() {
	bank := &Bank{balances: map[string]int{}}
	bank.Deposit("aziz", 100)

	fmt.Println("1-o'tkazma (60):", bank.Transfer("aziz", "madina", 60))
	fmt.Println("2-o'tkazma (60):", bank.Transfer("aziz", "madina", 60))
	fmt.Println(bank.balances)
}

