import (
	"fmt"
	"sort"
	"strings"
	"sync"
)

type Board struct {
	mu     sync.RWMutex
	scores map[string]int
}

func (b *Board) Add(player string, points int) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.scores[player] += points
}

func (b *Board) Top() string {
	b.mu.RLock()
	defer b.mu.RUnlock()
	names := make([]string, 0, len(b.scores))
	for n := range b.scores {
		names = append(names, n)
	}
	sort.Slice(names, func(i, j int) bool {
		if b.scores[names[i]] != b.scores[names[j]] {
			return b.scores[names[i]] > b.scores[names[j]]
		}
		return names[i] < names[j]
	})
	parts := make([]string, len(names))
	for i, n := range names {
		parts[i] = fmt.Sprintf("%d. %s (%d)", i+1, n, b.scores[n])
	}
	return strings.Join(parts, ", ")
}

func main() {
	board := &Board{scores: map[string]int{}}
	var writers sync.WaitGroup
	for _, p := range []string{"Aziz", "Madina", "Bobur"} {
		for range 10 {
			writers.Go(func() { board.Add(p, len(p)) })
		}
	}
	writers.Wait() // yozish bosqichi tugadi

	views := make([]string, 3)
	var readers sync.WaitGroup
	for i := range views {
		readers.Go(func() { views[i] = board.Top() })
	}
	readers.Wait()

	fmt.Println(views[0])
	fmt.Println("uchala o'quvchi bir xil jadvalni ko'rdi:", views[0] == views[1] && views[1] == views[2])
}

