func (c *Memo) Square(key int) int {
	// yangi OnceValue yaratamiz, lekin saqlanadigani faqat birinchisi
	entry, _ := c.m.LoadOrStore(key, sync.OnceValue(func() int {
		c.calls.Add(1) // "qimmat" hisob
