import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

func withTimeout(d time.Duration, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx, cancel := context.WithTimeout(r.Context(), d)
		defer cancel()
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func work(delay time.Duration) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		select {
		case <-time.After(delay):
			fmt.Fprint(w, "tayyor")
		case <-r.Context().Done():
			http.Error(w, "vaqt tugadi", http.StatusGatewayTimeout)
		}
	}
}

func main() {
	for _, delay := range []time.Duration{time.Millisecond, 3 * time.Second} {
		h := withTimeout(500*time.Millisecond, work(delay))
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
		fmt.Printf("ish %v -> %d %s\n", delay, rec.Code, strings.TrimSpace(rec.Body.String()))
	}
}

