import (
	"context"
	"fmt"
	"sort"
	"sync"
)

type Manager struct {
	mu      sync.Mutex
	cancels map[string]context.CancelFunc
	wg      sync.WaitGroup
}

func NewManager() *Manager {
	return &Manager{cancels: map[string]context.CancelFunc{}}
}

func (m *Manager) Start(name string, run func(ctx context.Context)) {
	ctx, cancel := context.WithCancel(context.Background())
	m.mu.Lock()
	m.cancels[name] = cancel
	m.mu.Unlock()
	m.wg.Go(func() { run(ctx) })
}

func (m *Manager) Stop(name string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if cancel, ok := m.cancels[name]; ok {
		cancel()
		delete(m.cancels, name)
	}
}

func (m *Manager) Running() []string {
	m.mu.Lock()
	defer m.mu.Unlock()
	names := make([]string, 0, len(m.cancels))
	for name := range m.cancels {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func (m *Manager) StopAll() {
	for _, name := range m.Running() {
		m.Stop(name)
	}
	m.wg.Wait()
}

func main() {
	m := NewManager()
	for _, name := range []string{"email", "report", "cleanup"} {
		m.Start(name, func(ctx context.Context) { <-ctx.Done() })
	}
	fmt.Println("ishlayapti:", m.Running())

	m.Stop("email")
	fmt.Println("ishlayapti:", m.Running())

	m.StopAll()
	fmt.Println("ishlayapti:", m.Running())
}

