func ParallelMap[T, R any](items []T, workers int, f func(T) R) []R {
	out := make([]R, len(items))
	idx := make(chan int)

	var wg sync.WaitGroup
	for range workers {
		wg.Go(func() {
			for i := range idx {
				out[i] = f(items[i])
			}
		})
	}
	for i := range items {
		idx <- i
	}
	close(idx)
	wg.Wait()
	return out
}

func main() {
	nums := []int{1, 2, 3, 4, 5, 6, 7, 8}

	squares := ParallelMap(nums, 3, func(n int) int { return n * n })
	labels := ParallelMap(nums, 2, func(n int) string { return fmt.Sprintf("#%d", n) })

	fmt.Println(squares)
	fmt.Println(labels)
}

