import (
	"fmt"
	"sort"
	"sync"
)

type Pool struct {
	jobs chan func()
	wg   sync.WaitGroup
}

func NewPool(workers, queue int) *Pool {
	p := &Pool{jobs: make(chan func(), queue)}
	for range workers {
		p.wg.Go(func() {
			for job := range p.jobs {
				job()
			}
		})
	}
	return p
}

func (p *Pool) Submit(job func()) { p.jobs <- job }

// Close yangi ish qabul qilmaydi va mavjudlari tugashini kutadi.
func (p *Pool) Close() {
	close(p.jobs)
	p.wg.Wait()
}

func main() {
	pool := NewPool(3, 10)

	var mu sync.Mutex
	var done []int
	for i := 1; i <= 8; i++ {
		pool.Submit(func() {
			mu.Lock()
			done = append(done, i*i)
			mu.Unlock()
		})
	}
	pool.Close()

	sort.Ints(done)
	fmt.Println(done)
}

