	"sync"
)

func rangeSum(from, to int) int { // [from, to) yig'indisi
	total := 0
	for i := from; i < to; i++ {
		total += i
	}
	return total
}

func main() {
	const n = 1_000_000
	const parts = 4
	size := n / parts

	partial := make([]int, parts)
	var wg sync.WaitGroup
	for p := range parts {
		wg.Go(func() {
			partial[p] = rangeSum(p*size+1, (p+1)*size+1)
		})
	}
	wg.Wait()

	total := 0
	for _, s := range partial {
		total += s
	}
	fmt.Println("parallel:", total)
	fmt.Println("formula: ", n*(n+1)/2)
	fmt.Println("teng:", total == n*(n+1)/2)
}

