}

type Crawler struct {
	mu      sync.Mutex
	visited map[string]bool
	wg      sync.WaitGroup
}

func (c *Crawler) Visit(url string) {
	c.mu.Lock()
	if c.visited[url] {
		c.mu.Unlock()
		return
	}
	c.visited[url] = true
	c.mu.Unlock()

	for _, next := range links[url] {
		c.wg.Go(func() { c.Visit(next) })
	}
}

