				if n <= old || peak.CompareAndSwap(old, n) {
					break
				}
			}
			time.Sleep(5 * time.Millisecond)
			active.Add(-1)
		})
	}
	wg.Wait()

	fmt.Println("limit:", limit)
	fmt.Println("bir vaqtda ishlaganlar limitdan oshmadi:", peak.Load() <= limit)
}

