func limit(n int, next http.Handler) http.Handler {
	sem := make(chan struct{}, n)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case sem <- struct{}{}:
			defer func() { <-sem }()
			next.ServeHTTP(w, r)
		default:
			http.Error(w, "server band", http.StatusServiceUnavailable)
		}
	})
}

func main() {
	started := make(chan struct{})
	release := make(chan struct{})
	slow := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(started)
		<-release // birinchi so'rov shu yerda "ushlab turiladi"
		fmt.Fprint(w, "tayyor")
	})
	h := limit(1, slow)

	first := make(chan string)
	go func() {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
		first <- fmt.Sprintf("%d %s", rec.Code, rec.Body.String())
	}()
	<-started // birinchi so'rov ichkarida

	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/", nil))
	fmt.Println("ikkinchi:", rec.Code, strings.TrimSpace(rec.Body.String()))

	close(release)
	fmt.Println("birinchi:", <-first)
}

