func orderedMap(in []int, workers int, f func(int) int) <-chan int {
	jobs := make(chan item)
	done := make(chan item)

	var wg sync.WaitGroup
	for range workers {
		wg.Go(func() {
			for it := range jobs {
				done <- item{it.idx, f(it.val)}
			}
		})
	}
	go func() {
		for i, v := range in {
