		defer close(out)
		pending := map[int]int{} // erta kelgan natijalar
		next := 0                // navbatdagi chiqishi kerak bo'lgan indeks
		for it := range done {
			pending[it.idx] = it.val
			for {
				v, ok := pending[next]
				if !ok {
					break
				}
				out <- v
				delete(pending, next)
				next++
			}
		}
	}()
	return out
}

func main() {
	nums := []int{1, 2, 3, 4, 5, 6}
	slowSmall := func(n int) int {
		time.Sleep(time.Duration(7-n) * 3 * time.Millisecond) // kichik son = sekinroq
		return n * n
	}
	for v := range orderedMap(nums, 3, slowSmall) {
		fmt.Println(v)
	}
}

