type Stage func(<-chan int) <-chan int

func gen(nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			out <- n
		}
	}()
	return out
}

func Compose(stages ...Stage) Stage {
	return func(in <-chan int) <-chan int {
		for _, s := range stages {
			in = s(in)
		}
		return in
	}
}

func Mul(k int) Stage {
	return func(in <-chan int) <-chan int {
		out := make(chan int)
		go func() {
			defer close(out)
			for v := range in {
				out <- v * k
			}
		}()
		return out
	}
}

func Add(k int) Stage {
	return func(in <-chan int) <-chan int {
		out := make(chan int)
		go func() {
			defer close(out)
			for v := range in {
				out <- v + k
			}
		}()
		return out
	}
}

func Only(pred func(int) bool) Stage {
	return func(in <-chan int) <-chan int {
		out := make(chan int)
		go func() {
			defer close(out)
			for v := range in {
				if pred(v) {
					out <- v
				}
			}
		}()
		return out
	}
}

