func Retry(ctx context.Context, attempts int, base time.Duration, f func() error) error {
	delay := base
	var err error
	for i := 1; i <= attempts; i++ {
		if err = f(); err == nil {
			return nil
		}
		select {
		case <-time.After(delay):
			delay *= 2 // 1s, 2s, 4s...
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return fmt.Errorf("%d urinishdan keyin: %w", attempts, err)
}

