	"fmt"
	"time"
)

type state int

const (
	closed state = iota
	open
	halfOpen
)

func (s state) String() string { return [...]string{"yopiq", "ochiq", "yarim ochiq"}[s] }

var ErrOpen = errors.New("breaker ochiq")

type Breaker struct {
	state     state
	failures  int
	threshold int
	cooldown  time.Duration
	openUntil time.Time
}

func (b *Breaker) Call(now time.Time, f func() error) error {
	if b.state == open {
		if now.Before(b.openUntil) {
			return ErrOpen
		}
		b.state = halfOpen // sovish tugadi: bitta sinov
	}
	err := f()
	if err != nil {
		b.failures++
		if b.state == halfOpen || b.failures >= b.threshold {
			b.state = open
			b.openUntil = now.Add(b.cooldown)
			b.failures = 0
		}
		return err
	}
	b.state, b.failures = closed, 0
	return nil
}

func main() {
	t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	b := &Breaker{threshold: 3, cooldown: 10 * time.Second}
	fail := func() error { return errors.New("servis ishlamayapti") }
	ok := func() error { return nil }

	steps := []struct {
		at int
		f  func() error
	}{{0, fail}, {1, fail}, {2, fail}, {3, ok}, {12, ok}}
	for _, s := range steps {
		err := b.Call(t0.Add(time.Duration(s.at)*time.Second), s.f)
		fmt.Printf("t=%2ds natija: %-22v holat: %v\n", s.at, err, b.state)
	}
}

