type Broker struct {
	mu   sync.RWMutex
	subs map[string][]chan string
}

func NewBroker() *Broker { return &Broker{subs: map[string][]chan string{}} }

func (b *Broker) Subscribe(topic string) (<-chan string, func()) {
	ch := make(chan string, 8)
	b.mu.Lock()
	b.subs[topic] = append(b.subs[topic], ch)
	b.mu.Unlock()

	var once sync.Once
	cancel := func() {
		once.Do(func() {
			b.mu.Lock()
			defer b.mu.Unlock()
			b.subs[topic] = slices.DeleteFunc(b.subs[topic], func(c chan string) bool { return c == ch })
			close(ch)
		})
	}
	return ch, cancel
}

func (b *Broker) Publish(topic, msg string) {
	b.mu.RLock()
	defer b.mu.RUnlock()
	for _, ch := range b.subs[topic] {
		ch <- msg
	}
}

func collect(ch <-chan string) []string {
	var all []string
	for msg := range ch {
		all = append(all, msg)
	}
	return all
}

func main() {
	b := NewBroker()
	a, cancelA := b.Subscribe("t")
	c, cancelC := b.Subscribe("t")

	b.Publish("t", "1")
	cancelA() // A "1" dan keyin ketadi
	b.Publish("t", "2")
	cancelC()
	cancelC() // ikkinchi chaqiruv zararsiz

