type getReq struct {
	key   string
	reply chan int
}

type Counter struct {
	incr chan string
	get  chan getReq
}

func NewCounter() *Counter {
	c := &Counter{incr: make(chan string), get: make(chan getReq)}
	go c.loop()
	return c
}

func (c *Counter) loop() {
	counts := map[string]int{} // faqat shu goroutine'ga tegishli
	for {
		select {
		case key := <-c.incr:
			counts[key]++
		case r := <-c.get:
			r.reply <- counts[r.key]
		}
	}
}

func (c *Counter) Inc(key string) { c.incr <- key }

func (c *Counter) Get(key string) int {
	reply := make(chan int)
	c.get <- getReq{key, reply}
	return <-reply
}

func main() {
	c := NewCounter()

	var wg sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg.Go(func() {
			if i%2 == 0 {
				c.Inc("olma")
			} else {
				c.Inc("nok")
			}
		})
	}
	wg.Wait()

	fmt.Println("olma:", c.Get("olma"))
	fmt.Println("nok:", c.Get("nok"))
}

