func merge(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	return append(out, b[j:]...)
}

func main() {
	data := []int{9, 3, 7, 1, 8, 2, 6, 4, 5, 0}
	mid := len(data) / 2

	var wg sync.WaitGroup
	wg.Go(func() { slices.Sort(data[:mid]) })
	wg.Go(func() { slices.Sort(data[mid:]) })
	wg.Wait()

	fmt.Println("yarmlar:", data[:mid], data[mid:])
	fmt.Println("birlashtirilgan:", merge(data[:mid], data[mid:]))
}

