var ErrTimeout = errors.New("vaqt tugadi")

func slowCall() int {
	time.Sleep(100 * time.Millisecond)
	return 42
}

func call(buffered bool, timeout time.Duration) (int, error) {
	size := 0
	if buffered {
		size = 1
	}
	ch := make(chan int, size)
	go func() { ch <- slowCall() }()

	select {
	case v := <-ch:
		return v, nil
	case <-time.After(timeout):
		return 0, ErrTimeout
	}
}

func main() {
	for _, buffered := range []bool{false, true} {
		base := runtime.NumGoroutine()
		_, err := call(buffered, 5*time.Millisecond)
		time.Sleep(400 * time.Millisecond) // slowCall tugab, yozishga ulgurishi uchun
		fmt.Printf("bufer=%-5v xato=%v | qolgan goroutine: %d\n", buffered, err, runtime.NumGoroutine()-base)
	}
}

