import (
	"fmt"
	"runtime"
	"sync"
	"time"
)

func settled(want int, limit time.Duration) bool {
	deadline := time.Now().Add(limit)
	for time.Now().Before(deadline) {
		if runtime.NumGoroutine() <= want {
			return true
		}
		time.Sleep(time.Millisecond)
	}
	return runtime.NumGoroutine() <= want
}

func checkLeak(name string, f func()) {
	before := runtime.NumGoroutine()
	f()
	if settled(before, 300*time.Millisecond) {
		fmt.Println(name+":", "leak yo'q")
		return
	}
	fmt.Printf("%s: %d ta goroutine qoldi\n", name, runtime.NumGoroutine()-before)
}

func main() {
	checkLeak("toza", func() {
		var wg sync.WaitGroup
		for range 3 {
			wg.Go(func() { time.Sleep(time.Millisecond) })
		}
		wg.Wait()
	})

	checkLeak("leakli", func() {
		block := make(chan struct{})
		for range 2 {
			go func() { <-block }() // hech qachon ochilmaydi
		}
	})
}

