func every(ctx context.Context, d time.Duration, f func(n int)) {
	ticker := time.NewTicker(d)
	defer ticker.Stop()
	for n := 1; ; n++ {
		select {
		case <-ticker.C:
			f(n)
		case <-ctx.Done():
			return
		}
	}
}

