package retry

import (
	"context"
	"fmt"
	"time"
)

func Retry(ctx context.Context, attempts int, base time.Duration, f func() error) error {
	delay := base
	var err error
	for i := 1; i <= attempts; i++ {
		if err = f(); err == nil {
			return nil
		}
		if i == attempts {
			break
		}
		select {
		case <-time.After(delay):
			delay *= 2
		case <-ctx.Done():
			return fmt.Errorf("to'xtatildi: %w", ctx.Err())
		}
	}
	return fmt.Errorf("%d urinish: %w", attempts, err)
}

