import (
	"fmt"
	"sync"
	"sync/atomic"
	"testing"
	"testing/synctest"
	"time"
)

type call struct {
	wg  sync.WaitGroup
	val string
}

type Flight struct {
	mu    sync.Mutex
	calls map[string]*call
}

func (f *Flight) Do(key string, fn func() string) string {
	f.mu.Lock()
	if c, ok := f.calls[key]; ok { // bu kalit uchun chaqiruv allaqachon ketmoqda
		f.mu.Unlock()
		c.wg.Wait()
		return c.val
	}
	c := &call{}
	c.wg.Add(1)
	if f.calls == nil {
		f.calls = map[string]*call{}
	}
	f.calls[key] = c
	f.mu.Unlock()

	c.val = fn()
	c.wg.Done()

	f.mu.Lock()
	delete(f.calls, key)
	f.mu.Unlock()
	return c.val
}

func TestSingleflight(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		var f Flight
		var loads atomic.Int32
		load := func() string {
			loads.Add(1)
			time.Sleep(time.Second) // sekin baza so'rovi
			return "foydalanuvchi-1"
		}

		results := make([]string, 5)
		var wg sync.WaitGroup
		for i := range results {
			wg.Go(func() { results[i] = f.Do("user:1", load) })
		}
		wg.Wait()

		fmt.Println(results)
		fmt.Println("load chaqiruvlari:", loads.Load())
	})
}

