func Async[T any](f func() T) func() T {
	ch := make(chan T, 1)
	go func() { ch <- f() }()

	var once sync.Once
	var val T
	return func() T {
		once.Do(func() { val = <-ch })
		return val
	}
}

func main() {
	price := Async(func() float64 { time.Sleep(20 * time.Millisecond); return 19.99 })
	stock := Async(func() int { time.Sleep(10 * time.Millisecond); return 7 })
	name := Async(func() string { return "Olma" })

	// uch ish parallel ketmoqda, natijalarni kerak bo'lganda kutamiz
	fmt.Println(name(), price(), stock())
	fmt.Println("ikkinchi o'qish:", price())
}

