import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type Server struct {
	queue chan func()
	wg    sync.WaitGroup
}

func NewServer(workers int) *Server {
	s := &Server{queue: make(chan func(), 16)}
	for range workers {
		s.wg.Go(func() {
			for job := range s.queue {
				job()
			}
		})
	}
	return s
}

func (s *Server) Submit(job func()) { s.queue <- job }

func (s *Server) Shutdown(ctx context.Context) error {
	close(s.queue) // yangi ish qabul qilinmaydi
	finished := make(chan struct{})
	go func() {
		s.wg.Wait()
		close(finished)
	}()
	select {
	case <-finished:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func main() {
	var done atomic.Int32
	s := NewServer(2)
	for range 6 {
		s.Submit(func() {
			time.Sleep(2 * time.Millisecond)
			done.Add(1)
		})
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	fmt.Println("Shutdown:", s.Shutdown(ctx), "| bajarildi:", done.Load())

	stuck := NewServer(1)
	stuck.Submit(func() { time.Sleep(3 * time.Second) })
	ctx2, cancel2 := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel2()
	fmt.Println("Shutdown (osilgan ish):", stuck.Shutdown(ctx2))
}

