import (
	"context"
	"fmt"
	"slices"
	"sort"
	"sync"
	"time"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 300*time.Millisecond)
	defer cancel()

	services := []struct {
		name  string
		delay time.Duration
	}{
		{"narx", 5 * time.Millisecond},
		{"zaxira", 10 * time.Millisecond},
		{"sharhlar", 3 * time.Second},
		{"tavsiya", 4 * time.Second},
	}

	out := make(chan string)
	var wg sync.WaitGroup
	for _, s := range services {
		wg.Go(func() {
			select {
			case <-time.After(s.delay):
				select {
				case out <- s.name:
				case <-ctx.Done():
				}
			case <-ctx.Done():
			}
		})
	}
	go func() {
		wg.Wait()
		close(out)
	}()

	var got []string
	for name := range out {
		got = append(got, name)
	}
	sort.Strings(got)

	var missing []string
	for _, s := range services {
		if !slices.Contains(got, s.name) {
			missing = append(missing, s.name)
		}
	}
	sort.Strings(missing)
	fmt.Println("kelgan:", got)
	fmt.Println("kelmadi:", missing)
}
